#include <limits>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::float_denorm_style denorm = std::numeric_limits<double>::has_denorm;
    std::float_round_style rounding = std::numeric_limits<double>::round_style;
    assert(denorm == std::denorm_absent || denorm == std::denorm_present ||
        denorm == std::denorm_indeterminate);
    assert(rounding >= std::round_indeterminate &&
        rounding <= std::round_toward_neg_infinity);
}
